// @generated by:gauntlet run:godseye-local-jobs
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { deferred, type JobsFixture, jobsFixture, never } from "./jobs-helpers.js";

const probeInput = {
  expectedState: "unknown" as const,
  resolution: "probe_read_only" as const,
  evidenceRef: "owner:ticket-0001",
};
describe("T18 job fault injection", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  const limits = (maxAttempts: number) => ({
    maxConcurrent: 1,
    maxAttempts,
    timeoutSeconds: 30,
    retentionDays: 7,
  });

  it("retries a confirmed failure of an idempotent job with a stable effect key", async () => {
    const definition = await fixture.register({ limits: limits(3) });
    let attempts = 0;
    fixture.handler.script = async () => ({
      status: ++attempts < 2 ? "failed" : "succeeded",
      evidenceRef: `fixture:attempt-${attempts}`,
    });
    const run = await fixture.trigger(definition.id, 0, "retry-key-0001");
    await fixture.work();
    await fixture.work();
    const settled = await fixture.state(run.id);
    expect(settled).toMatchObject({ state: "succeeded", attempt: 2 });
    expect(new Set(fixture.handler.calls.map((call) => call.effectKey))).toEqual(
      new Set([`job:${run.id}`]),
    );
    expect(new Set(fixture.handler.calls.map((call) => call.attemptKey)).size).toBe(2);
  });
  it("stops retrying at the attempt limit and reports failure", async () => {
    const definition = await fixture.register({ limits: limits(2) });
    fixture.handler.script = async () => ({ status: "failed", evidenceRef: "fixture:no" });
    const run = await fixture.trigger(definition.id, 0, "retry-key-0002");
    for (let i = 0; i < 4; i++) await fixture.work();
    expect(await fixture.state(run.id)).toMatchObject({ state: "failed", attempt: 2 });
    expect(fixture.handler.calls).toHaveLength(2);
  });
  it("never retries a protected effect that failed or became uncertain", async () => {
    const definition = await fixture.register({
      effectPolicy: "protected",
      limits: limits(5),
    });
    fixture.handler.script = async () => {
      throw new Error("socket closed mid-effect");
    };
    const run = await fixture.trigger(definition.id, 0, "protected-0001");
    for (let i = 0; i < 3; i++) await fixture.work();
    expect(await fixture.state(run.id)).toMatchObject({ state: "unknown", attempt: 1 });
    expect(fixture.handler.calls).toHaveLength(1);
  });
  it("moves an unknown protected effect through owner reconciliation using read-only evidence", async () => {
    const definition = await fixture.register({ effectPolicy: "protected", limits: limits(5) });
    fixture.handler.script = async () => {
      throw new Error("lost acknowledgement");
    };
    fixture.handler.probe = async () => ({
      status: "succeeded",
      evidenceRef: "observed:receipt-9",
    });
    const run = await fixture.trigger(definition.id, 0, "protected-0002");
    await fixture.work();
    const reconciled = await fixture
      .jobs()
      .reconcileRun(fixture.freshOwner(), run.id, probeInput, randomUUID());
    expect(reconciled.state).toBe("succeeded");
    expect(fixture.handler.calls).toHaveLength(1);
    expect(fixture.handler.probes).toHaveLength(1);
  });
  it("keeps an unprovable protected effect unknown instead of presenting success", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    fixture.handler.script = async () => ({ status: "unknown" });
    const run = await fixture.trigger(definition.id, 0, "protected-0003");
    await fixture.work();
    const result = await fixture
      .jobs()
      .reconcileRun(fixture.freshOwner(), run.id, probeInput, randomUUID());
    expect(result.state).toBe("unknown");
  });
  it("treats a timed-out protected job as unknown and a timed-out idempotent job as retryable", async () => {
    const protectedJob = await fixture.register({
      name: "slow-protected",
      effectPolicy: "protected",
    });
    fixture.handler.script = never;
    const run = await fixture.trigger(protectedJob.id, 0, "timeout-0000001");
    await fixture.work();
    expect((await fixture.state(run.id)).state).toBe("unknown");
    const idempotent = await fixture.register({ name: "slow-idem", limits: limits(2) });
    const second = await fixture.trigger(idempotent.id, 0, "timeout-0000002");
    for (let i = 0; i < 3; i++) await fixture.work();
    expect(await fixture.state(second.id)).toMatchObject({ state: "failed", attempt: 2 });
  });
  it("cancels queued work without ever invoking the handler", async () => {
    const definition = await fixture.register();
    const run = await fixture.trigger(definition.id, 0, "cancel-queued-01");
    const cancelled = await fixture
      .jobs()
      .cancel(fixture.freshOwner(), run.id, { reason: "operator abort" }, randomUUID());
    expect(cancelled.state).toBe("cancelled");
    await fixture.work();
    expect(fixture.handler.calls).toHaveLength(0);
  });
  it("cancels running work only after fencing and discards the late worker result", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    const started = deferred();
    const release = deferred();
    let lateOutbox: unknown = null;
    fixture.handler.script = async (context) => {
      started.resolve();
      await release.promise;
      lateOutbox = await context
        .outbox({ effectKey: "late-write-0001", destination: "fixture.sink", payload: {} })
        .catch((error: unknown) => error);
      return { status: "succeeded", evidenceRef: "late:result" };
    };
    const run = await fixture.trigger(definition.id, 0, "cancel-run-0001");
    await fixture.jobs().tick();
    const worker = fixture.infrastructure.foundation.tick("cancel-worker");
    await started.promise;
    const requested = await fixture
      .jobs()
      .cancel(fixture.freshOwner(), run.id, { reason: "operator abort" }, randomUUID());
    expect(requested.state).toBe("cancel_requested");
    await fixture.jobs().tick();
    expect((await fixture.state(run.id)).state).toBe("cancel_requested");
    release.resolve();
    await worker;
    await fixture.jobs().tick();
    const final = await fixture.state(run.id);
    expect(final.state).toBe("cancelled");
    expect(final.state).not.toBe("succeeded");
    expect(lateOutbox).toMatchObject({ code: "FENCED" });
    expect(await fixture.outboxRows()).toHaveLength(0);
  });
  it("lets a stale worker lease finish only into a fenced, unknown outcome", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    const started = deferred();
    const release = deferred();
    fixture.handler.script = async () => {
      started.resolve();
      await release.promise;
      return { status: "succeeded", evidenceRef: "late:result" };
    };
    const run = await fixture.trigger(definition.id, 0, "stale-lease-001");
    await fixture.jobs().tick();
    const worker = fixture.infrastructure.foundation.tick("stale-worker");
    await started.promise;
    fixture.clock.advance(120_000);
    await fixture.infrastructure.foundation.reconcileExpired();
    release.resolve();
    await worker;
    await fixture.jobs().tick();
    expect((await fixture.state(run.id)).state).toBe("unknown");
    expect(fixture.handler.calls).toHaveLength(1);
  });
  it("resumes persisted work after a controller restart without duplicating a started effect", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    const queued = await fixture.trigger(definition.id, 0, "restart-key-001");
    await fixture.jobs().tick();
    const restarted = fixture.build();
    await restarted.jobs.tick();
    expect(await restarted.foundation.tick("restart-worker")).toBe(true);
    await restarted.jobs.tick();
    expect((await fixture.state(queued.id)).state).toBe("succeeded");
    expect(fixture.handler.calls).toHaveLength(1);
    await restarted.jobs.tick();
    expect(await restarted.foundation.tick("restart-worker")).toBe(false);
    const rows = await fixture.store.db.select().from(schema.jobRuns);
    expect(rows).toHaveLength(1);
  });
});
